components/common/quick-search:
{{{ snippet "forms_search"}}}
<form class="form" action="{{urls.search}}">
    <fieldset class="form-fieldset">
        <div class="form-field">
            {{#if theme_settings.themevale_header-search-category}}
                <div id="search_category">
                    <select name="category" class="select_category">
                        <option value="" selected="">All</option>
                        {{#each categories}}
                            <option value="{{id}}">{{name}}</option>
                            {{#if children}}
                                {{#each children}}
                                    <option value="{{id}}">&ndash;&ndash;&ndash; {{name}}</option>
                                    {{#if children}}
                                        {{#each children}}
                                            <option value="{{id}}">&ndash;&ndash;&ndash;&ndash;&ndash;&ndash; {{name}}</option>
                                            {{#if children}}
                                                {{#each children}}
                                                    {{#if children}}
                                                        <option value="{{id}}">&ndash;&ndash;&ndash;&ndash;&ndash;&ndash;&ndash;&ndash;&ndash; {{name}}</option>
                                                    {{else}}
                                                        <option value="{{id}}">&ndash;&ndash;&ndash;&ndash;&ndash;&ndash;&ndash;&ndash;&ndash; {{name}}</option>
                                                    {{/if}}
                                                {{/each}}
                                            {{/if}}
                                        {{/each}}
                                    {{/if}}
                                {{/each}}
                            {{/if}}
                        {{/each}}
                    </select> 
                    <svg class="icon"><use xlink:href="#icon-chevron-down" /></svg>
                </div>
            {{/if}}
            <input class="form-input" data-search-quick name="search_query" id="search_query" data-error-message="{{lang 'search.error.empty_field'}}" placeholder="{{lang 'search.quick_search.input_quickSearch'}}" autocomplete="off">
            <button type="submit"><svg class="icon"><use xlink:href="#icon-search"></use></svg></button>
        </div>
    </fieldset>
</form>
<div class="quickSearchResults" data-bind="html: results"></div>

components/common/currency-selector:
{{#if currency_selector.currencies.length '>' 1}}
<ul class="navUser-section">
    <li class="navUser-item">
        <a class="navUser-action navUser-action--currencySelector" href="#">
            <span class="image-flag">{{{currency_selector.active_currency_flag}}}</span> 
            <span class="text-flag">{{lang 'common.currency' code=currency_selector.active_currency_code}}</span>
            <i class="icon" aria-hidden="true"><svg><use xlink:href="#icon-chevron-down" /></svg></i></a>
        <ul class="dropdown-menu" id="currencySelection">
            {{#each currency_selector.currencies}}
            <li class="dropdown-menu-item">
                <a href="{{{switch_url}}}">
                    {{#if is_active}}
                    {{{flag}}} <strong>{{name}}</strong>
                    {{else}}
                    {{{flag}}} {{name}}
                    {{/if}}
                </a>
            </li>
            {{/each}}
        </ul>
    </li>
</ul>
{{/if}}

components/common/navigation-list-altern:
{{#if children}}
    <p class="navPages-action navPages-action-depth-max has-subMenu is-root" data-label="{{url}}">
        <a class="text" href="{{url}}">{{name}}</a>
        <span class="navPages-action-moreIcon" aria-hidden="true">
            <svg class="icon"><use xlink:href="#icon-chevron-down" /></svg>
        </span>
    </p>
    {{> components/common/navigation-dropdown}}
{{else}}
    <a class="navPages-action navPages-action-end" data-label="{{url}}" href="{{url}}"><span class="text">{{name}}</span></a>
{{/if}}

